// Run against the isolated profile generated by prepare-native-qualification.py.
// Real WebKit/Tauri IPC, OS keyring and SQLite; no licence override or IPC mock.
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(process.argv[2]);
const manifest = JSON.parse(readFileSync(resolve(root, 'fixture-manifest.json'), 'utf8'));
if (manifest.baseline !== '252e0b267b6d67585b6916bce2ce29f516685fd8') throw Error('Wrong fixture');
async function baseline(root) {
  const invoke = window.__TAURI_INTERNALS__.invoke;
  const report = [];
  const workspace = await invoke('get_active_workspace');
  if (!workspace.path.startsWith(root + '/')) throw Error('Refusing a non-fixture profile');
  await invoke('switch_to_default_workspace');
  if (!(await invoke('get_vault_status')).has_master_password) {
    await invoke('setup_master_password', { password: 'Qualification-Only-2026!' });
  }
  await invoke('unlock_vault', { password: 'Qualification-Only-2026!' });
  function check(name, condition, detail) {
    report.push({ name, passed: !!condition, detail });
    if (!condition) throw new Error(JSON.stringify(report));
  }
  const conns = await invoke('list_saved_connections', { projectId: 'default' });
  check(
    'legacy global connection',
    conns.some(x => x.id === 'legacy-default')
  );
  const credentials = await invoke('get_connection_credentials', {
    projectId: 'default',
    connectionId: 'legacy-default',
  });
  check(
    'legacy secret keyring lookup',
    credentials.success && credentials.password === 'synthetic-password-legacy-default'
  );
  const opened = await invoke('connect_saved_connection', {
    projectId: 'default',
    connectionId: 'legacy-default',
  });
  check('connect SQLite', opened.success, opened);
  window.__qualificationSession = opened.session_id;
  const preview = await invoke('preview_table', {
    sessionId: opened.session_id,
    namespace: { database: 'main', schema: null },
    table: 'items',
    limit: 10,
    bypassCache: true,
  });
  check('real SQLite preview', preview.success, preview);
  check(
    'mask retained without Pro licence',
    JSON.stringify(preview).includes('••••••') &&
      !JSON.stringify(preview).includes('synthetic@example.invalid')
  );
  check('exact integer over native IPC', JSON.stringify(preview).includes('9007199254740993'));
  for (const command of ['get_time_travel_config']) {
    let error;
    try {
      await invoke(command);
    } catch (e) {
      error = String(e);
    }
    check(command + ' requires Pro', !!error, error);
  }
  const changedMask = await invoke('set_connection_masking', {
    projectId: 'default',
    connectionId: 'legacy-default',
    masking: {
      rules: [{ table: 'items', column: 'label', mode: 'hidden' }],
      mask_detected_columns: false,
    },
  });
  check('new masking denied to Core', !changedMask.success, changedMask);
  const maskAfter = (await invoke('list_saved_connections', { projectId: 'default' }))[0].masking;
  check(
    'denied mask preserves old rules',
    JSON.stringify(maskAfter) === JSON.stringify(conns.find(x => x.id === 'legacy-default').masking)
  );
  await invoke('lock_vault');
  const locked = await invoke('get_connection_credentials', {
    projectId: 'default',
    connectionId: 'legacy-default',
  });
  check('locked credential read denied', !locked.success, locked);
  const wrong = await invoke('unlock_vault', { password: 'wrong-synthetic-password' });
  check('wrong password denied', !wrong.success, wrong);
  check(
    'unlock master password',
    (await invoke('unlock_vault', { password: 'Qualification-Only-2026!' })).success
  );
  const snapshotId = '1325d1c7-7d46-4c1a-a4c9-9bd62ab0ca57';
  const snapshot = await invoke('get_snapshot', { snapshotId });
  check('legacy snapshot exact read', snapshot.success && JSON.stringify(snapshot).includes('9007199254740993'));
  const renamed = await invoke('rename_snapshot', { snapshotId, newName: 'Capture vérifiée' });
  check('snapshot metadata save', renamed.success);
  const reopened = await invoke('get_snapshot', { snapshotId });
  check('snapshot data retained after rename', reopened.meta.name === 'Capture vérifiée' && JSON.stringify(reopened.result) === JSON.stringify(snapshot.result));
  return report;
}
async function workflows(root) {
  const invoke = window.__TAURI_INTERNALS__.invoke;
  const report = [];
  function check(name, condition, detail) {
    report.push({ name, passed: !!condition, detail });
    if (!condition) throw new Error(JSON.stringify(report));
  }
  const initialConnections = await invoke('list_saved_connections', { projectId: 'default' });
  let expected = initialConnections.find(x => x.id === 'legacy-default');
  const duplicate = await invoke('duplicate_saved_connection', {
    projectId: 'default',
    connectionId: expected.id,
  });
  check('duplicate saved connection', duplicate.success, duplicate.error);
  const copy = duplicate.connection;
  check(
    'duplicate preserves metadata and mask',
    copy.id !== expected.id && JSON.stringify(copy.masking) === JSON.stringify(expected.masking)
  );
  check(
    'edit saved connection',
    (
      await invoke('save_connection', {
        input: {
          ...copy,
          name: 'Disposable edited duplicate',
          password: 'synthetic-password-legacy-default',
        },
      })
    ).success
  );
  check(
    'edit persisted',
    (await invoke('list_saved_connections', { projectId: 'default' })).some(
      x => x.id === copy.id && x.name === 'Disposable edited duplicate'
    )
  );
  check(
    'delete saved connection',
    (await invoke('delete_saved_connection', { projectId: 'default', connectionId: copy.id }))
      .success
  );
  check(
    'delete preserves original',
    (await invoke('list_saved_connections', { projectId: 'default' })).length ===
      initialConnections.length
  );
  const fresh = {
    ...expected,
    id: 'native-new',
    name: 'Native new connection',
    masking: { rules: [], mask_detected_columns: false },
    password: 'native-synthetic-password',
  };
  check('create saved connection', (await invoke('save_connection', { input: fresh })).success);
  check(
    'created credentials round trip',
    (await invoke('get_connection_credentials', { projectId: 'default', connectionId: fresh.id }))
      .password === fresh.password
  );
  check(
    'cleanup new connection',
    (await invoke('delete_saved_connection', { projectId: 'default', connectionId: fresh.id }))
      .success
  );
  const sessionId = window.__qualificationSession;
  const update = await invoke('update_row', {
    sessionId,
    database: 'main',
    schema: null,
    table: 'items',
    primaryKey: { columns: { id: 1 } },
    data: { columns: { label: 'Après qualification' } },
  });
  check('native row mutation', update.success, update);
  const read = await invoke('preview_table', {
    sessionId,
    namespace: { database: 'main', schema: null },
    table: 'items',
    limit: 10,
    bypassCache: true,
  });
  check(
    'mutation readback exact and masked',
    read.success &&
      JSON.stringify(read).includes('Après qualification') &&
      JSON.stringify(read).includes('9007199254740993') &&
      !JSON.stringify(read).includes('synthetic@example.invalid')
  );
  const bad = await invoke('update_row', {
    sessionId,
    database: 'main',
    schema: null,
    table: 'items',
    primaryKey: { columns: { id: 1 } },
    data: { columns: { label: null } },
  });
  check('constraint failure reported', !bad.success, bad.error);
  const alpha = await invoke('open_workspace', { qoredbPath: root + '/alpha/.qoredb' });
  check('open alpha', alpha.success);
  const aid = await invoke('get_workspace_project_id');
  const aconns = await invoke('list_saved_connections', { projectId: aid });
  check(
    'alpha retains own connection',
    aconns.length === 1 && aconns[0].id === 'legacy-alpha' && aconns[0].project_id === aid
  );
  check(
    'alpha keyring identity',
    (await invoke('get_connection_credentials', { projectId: aid, connectionId: 'legacy-alpha' }))
      .password === 'synthetic-password-legacy-alpha'
  );
  const lib = await invoke('ws_get_query_library', { projectId: aid });
  check(
    'legacy library read',
    lib.items[0].id === 'legacy-query' && lib.folders[0].id === 'legacy-folder'
  );
  lib.items[0].title = 'Requête modifiée en natif';
  check('library save', await invoke('ws_save_query_library', { projectId: aid, library: lib }));
  check(
    'library reopen',
    (await invoke('ws_get_query_library', { projectId: aid })).items[0].title === lib.items[0].title
  );
  check(
    'open beta',
    (await invoke('open_workspace', { qoredbPath: root + '/beta/.qoredb' })).success
  );
  const bid = await invoke('get_workspace_project_id');
  for (const [command, args] of [
    ['list_saved_connections', {}],
    ['delete_saved_connection', { connectionId: 'legacy-alpha' }],
    ['get_connection_credentials', { connectionId: 'legacy-alpha' }],
    ['ws_save_query_library', { library: lib }],
  ]) {
    let error;
    try {
      await invoke(command, { projectId: aid, ...args });
    } catch (e) {
      error = String(e);
    }
    check('stale ' + command + ' rejected', !!error, error);
  }
  check(
    'beta library unaffected',
    (await invoke('ws_get_query_library', { projectId: bid })).items[0].title ===
      'Requête conservée'
  );
  const failedOpen = await invoke('open_workspace', { qoredbPath: root + '/missing/.qoredb' });
  check('invalid workspace reports error', !failedOpen.success);
  check('failed open keeps beta', (await invoke('get_workspace_project_id')) === bid);
  await invoke('open_workspace', { qoredbPath: root + '/alpha/.qoredb' });
  check(
    'alpha library persisted across switch',
    (await invoke('ws_get_query_library', { projectId: aid })).items[0].title ===
      'Requête modifiée en natif'
  );
  await invoke('switch_to_default_workspace');
  return report;
}
const input = `const root=${JSON.stringify(root)}; const baseline=await (${baseline.toString()})(root); const workflows=await (${workflows.toString()})(root); return {baseline,workflows};`;
const result = spawnSync(
  process.execPath,
  [fileURLToPath(new URL('./native-webview-eval.mjs', import.meta.url))],
  { input, encoding: 'utf8', env: process.env }
);
process.stdout.write(result.stdout || '');
process.stderr.write(result.stderr || '');
process.exit(result.status ?? 1);
